import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BxGh02fV.js";const g=JSON.parse('{"title":"Objectifs et jalons","description":"","frontmatter":{"title":"Objectifs et jalons"},"headers":[],"relativePath":"guide/objectifs.md","filePath":"guide/objectifs.md"}'),n={name:"guide/objectifs.md"};function o(l,e,u,i,d,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="objectifs-et-jalons" tabindex="-1">Objectifs et jalons <a class="header-anchor" href="#objectifs-et-jalons" aria-label="Permalink to &quot;Objectifs et jalons&quot;">​</a></h1><p>Cet écran suit ce que vous voulez livrer : vos objectifs, les jalons qui les jalonnent et les livrables attendus à chaque jalon. Vous y venez pour savoir, d&#39;un coup d&#39;œil, ce qui est fini, ce qui manque, et pour dire vous-même « c&#39;est bon ».</p><p>L&#39;entrée <strong>Objectifs &amp; jalons</strong> (groupe <strong>Pilotage</strong> de la barre latérale) n&#39;apparaît que si le projet a un registre de pilotage, ou si son modèle de projet prévoit des livrables. Un projet de logiciel sans objectif ne la voit pas.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>De haut en bas :</p><ul><li><strong>Relecture en attente</strong> : quand l&#39;équipe d&#39;agents s&#39;est arrêtée pour vous demander votre avis, un panneau en tête dit à quel rythme la relecture est prévue (à chaque tâche, à chaque étape, à chaque jalon ; « étape » prend le nom que votre modèle de projet donne à une story) et liste les livrables à relire, avec <strong>Accepter</strong> et <strong>Refuser</strong>. Un refus demande une note : elle repart à l&#39;analyste.</li><li><strong>L&#39;arbre du travail</strong> : chaque <strong>objectif</strong> contient ses <strong>jalons</strong>, et chaque jalon ses <strong>livrables</strong>. <ul><li>Un <strong>jalon</strong> montre son échéance, son état (<strong>à venir</strong>, <strong>en cours</strong>, <strong>atteint</strong>), son taux et l&#39;effort passé sur l&#39;effort estimé.</li><li>Un <strong>livrable</strong> montre son taux de complétude, une pastille colorée, ce qui lui manque et son état de relecture.</li></ul></li><li><strong>Sans objectif</strong> et <strong>Hors jalon</strong> : ce qui n&#39;est rattaché à rien reste visible, rangé dans ces deux groupes.</li><li><strong>Ressources</strong> : les personnes ou moyens qui font le travail.</li></ul><p>Le taux dit ce qui est <strong>présent</strong> par rapport à ce qui est prévu. Il ne juge pas la qualité : seule votre relecture dit qu&#39;un livrable est fini.</p><h3 id="les-couleurs" tabindex="-1">Les couleurs <a class="header-anchor" href="#les-couleurs" aria-label="Permalink to &quot;Les couleurs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pastille</th><th>Sens</th></tr></thead><tbody><tr><td>Gris</td><td>pas encore analysé</td></tr><tr><td>Rouge</td><td>moins de 50 %</td></tr><tr><td>Orange</td><td>de 50 à 99 %</td></tr><tr><td>Couleur d&#39;accent</td><td>100 %, pas encore relu</td></tr><tr><td>Vert</td><td>100 % et relu accepté</td></tr></tbody></table><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="relire-un-livrable" tabindex="-1">Relire un livrable <a class="header-anchor" href="#relire-un-livrable" aria-label="Permalink to &quot;Relire un livrable&quot;">​</a></h3><p>Quand un livrable a un rapport de complétude, il porte ses propres boutons <strong>Accepter</strong> et <strong>Refuser</strong> (le refus demande une note). Votre geste est enregistré comme venant de l&#39;écran, et il passe quel que soit le mode de travail des agents : c&#39;est vous qui décidez.</p><p>Si l&#39;équipe d&#39;agents attend justement votre relecture de ce livrable, ses boutons sont dans le panneau du haut : une seule décision par livrable. Tranchez-y, ou demandez à l&#39;agent de le faire avec votre réponse. Tant que l&#39;équipe attend, ce livrable ne se relit pas à part.</p><h3 id="le-point-d-attention-du-tableau-de-bord" tabindex="-1">Le point d&#39;attention du tableau de bord <a class="header-anchor" href="#le-point-d-attention-du-tableau-de-bord" aria-label="Permalink to &quot;Le point d&#39;attention du tableau de bord&quot;">​</a></h3><p>Quand une relecture vous attend, le <a href="/Effortless/guide/dashboard.html">Tableau de bord</a> affiche une section <strong>À relire</strong>, avec les livrables en attente (ou <strong>Relecture attendue</strong> suivi du rythme, par exemple « Relecture attendue (à chaque jalon) ») ; un clic ouvre cet écran.</p><h3 id="lier-la-carte-aux-livrables" tabindex="-1">Lier la Carte aux livrables <a class="header-anchor" href="#lier-la-carte-aux-livrables" aria-label="Permalink to &quot;Lier la Carte aux livrables&quot;">​</a></h3><p>Dans la <a href="/Effortless/guide/ontologie.html">Carte</a>, un atome de type solution, composant ou module peut citer un livrable : champ <strong>Livrable du registre</strong> du panneau. L&#39;élément montre alors, sur la Carte, une pastille colorée avec le pourcentage.</p><h2 id="les-surfaces-masquees-par-le-modele" tabindex="-1">Les surfaces masquées par le modèle <a class="header-anchor" href="#les-surfaces-masquees-par-le-modele" aria-label="Permalink to &quot;Les surfaces masquées par le modèle&quot;">​</a></h2><p>Un modèle de projet peut masquer ce qui n&#39;a pas de sens pour lui. Le modèle <code>gestion-de-projet</code> masque <strong>Dérive</strong>, <strong>Git</strong>, <strong>Modules</strong> et la tuile Git du tableau de bord. Ces surfaces sont <strong>absentes</strong>, pas grisées. Une vue masquée atteinte quand même (un onglet restauré, par exemple) retombe sur le Tableau de bord, et un point d&#39;attention qui mènerait à une vue masquée n&#39;est pas affiché.</p><h2 id="budget-edition-pro" tabindex="-1">Budget (édition Pro) <a class="header-anchor" href="#budget-edition-pro" aria-label="Permalink to &quot;Budget (édition Pro)&quot;">​</a></h2><blockquote><p><strong>Pro.</strong> Le budget n&#39;existe que dans l&#39;édition Pro.</p></blockquote><p>Sous les ressources, un panneau <strong>Budget</strong> suit l&#39;argent. Les montants sont saisis en euros (devise du projet, <code>EUR</code> par défaut) et gardés en centimes.</p><ul><li><strong>Postes</strong> : un montant prévu, le dépensé et l&#39;écart (calculé sur les dépenses seules).</li><li><strong>Dépenses</strong> : une liste, avec ajout et retrait.</li><li><strong>Main-d&#39;œuvre</strong> : par ressource, les minutes passées multipliées par le taux horaire. Les minutes d&#39;une ressource sans taux sont comptées à part, « sans tarif ».</li><li><strong>Totaux</strong> : prévu, dépenses, main-d&#39;œuvre et écart global (prévu moins dépenses et main-d&#39;œuvre).</li></ul><p>Les ressources y gagnent un genre (équipe, prestataire) et un taux horaire, également Pro. Ils ne se saisissent pas à l&#39;écran : demandez à l&#39;agent de les poser, par exemple « Mets Camille Martin à 60 € de l&#39;heure » ou « L&#39;atelier d&#39;impression est un prestataire ». Tant qu&#39;aucune ressource n&#39;a de taux, le panneau vous le rappelle.</p><p>Exemple fictif : poste « Impression des supports », prévu 1 200 €, une dépense de 450 € ; une ressource « Camille Martin » à 60 €/h avec 5 h passées ajoute 300 € de main-d&#39;œuvre ; l&#39;écart global est de 450 €.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>L&#39;agent lit et tient le registre ; voir <a href="/Effortless/agent/piloter.html#objectifs-jalons-et-livrables">Piloter le travail</a> et <a href="/Effortless/agent/boucle-equipe.html">La boucle équipe</a>. La relecture se tranche à l&#39;écran ou par l&#39;agent.</p>',27)])])}const b=t(n,[["render",o]]);export{g as __pageData,b as default};
